                    protocols[protocol_name]["dbpath"] = db_file_path
                if exists(db_nav_path):
                    protocols[protocol_name]["nvpath"] = db_nav_path
                if exists(protocol_args_path):
                    protocols[protocol_name]["argspath"] = protocol_args_path
        return protocols

